            })
        }
        AcceleratedPath::Idxd => {
            let device_path = args.accelerator_device.clone().ok_or_else(|| {
                "--accelerator-device is required with --accelerated-path idxd".to_string()
            })?;
            Ok(AcceleratedPathConfig {
