    "`accel-rpc/accel-middleware/src/lib.rs` already declares Tower middleware layers for hardware-accelerated gRPC operations: CRC-32C via DSA `copy_crc`, compression via IAX deflate.",
    "Tonic server builder supports Tower layers with `Server::builder().layer(...)`; docs show `ServiceBuilder` composition in `accel-rpc/tonic/tonic/src/transport/server/mod.rs`.",
    "Tonic services operate at `Service<Request<Body>, Response = Response<...>>` boundaries, and `tonic::body::Body::new` accepts any `http_body::Body<Data = bytes::Bytes> + Send + 'static`.",
    "`idxd-rust/src/idxd_async.rs` exposes `DsaEngine::{memmove, crc_gen, copy_crc}` as futures, but comments say it is a minimal polling engine with no runtime, interrupt, retry, cancellation, or validation policy."
  ],
  "interface_sketch": "```rust
pub trait AccelSubmit: Clone + Send + Sync + 'static {
    fn copy_crc(&self, src: Bytes, seed: u32) -> BoxFuture<'static, Result<CopyCrcDone, AccelError>>;
    fn memmove(&self, src: Bytes) -> BoxFuture<'static, Result<Bytes, AccelError>>;
}

#[derive(Clone)]
pub struct TokioDsaSubmitter { /* tokio Handle, DsaEngine pool, thresholds */ }

#[derive(Clone)]
pub struct AccelBodyLayer<A> {
    submitter: A,
    policy: AccelBodyPolicy,
}

pub struct AccelBodyService<S, A> { inner: S, submitter: A, policy: AccelBodyPolicy }

pub struct AccelBody<B, A> { inner: B, submitter: A, state: BodyState, policy: AccelBodyPolicy }

impl<S, A> Layer<S> for AccelBodyLayer<A> { type Service = AccelBodyService<S, A>; }

impl<S, B, A> Service<http::Request<B>> for AccelBodyService<S, A>
where
    S: Service<http::Request<AccelBody<B, A>>> ,
    B: http_body::Body<Data = Bytes> + Send + 'static,
    B::Error: Into<BoxError>,
    A: AccelSubmit,
{ /* wrap request body before inner.call; wrap response body on completion */ }

impl<B, A> http_body::Body for AccelBody<B, A>
where B: http_body::Body<Data = Bytes>, A: AccelSubmit
{ type Data = Bytes; type Error = tonic::Status; /* poll_frame drives body + submitted futures */ }
```",
  "worked_caller_example": "```rust
let dsa = TokioDsaSubmitter::open("/dev/dsa/wq0.0", tokio::runtime::Handle::current())?
    .with_min_bytes(4096)
    .with_software_fallback(true);

let accel_layer = AccelBodyLayer::new(dsa, AccelBodyPolicy {
    request_crc: true,
    response_crc: true,
    min_offload_bytes: 4096,
    max_coalesce_bytes: 1 << 20,
});

let layer = tower::ServiceBuilder::new()
    .layer(accel_layer)
    .into_inner();

tonic::transport::Server::builder()
    .layer(layer)
    .add_service(my_proto::my_server::MyServer::new(service))
    .serve(addr)
    .await?;
```",
